<?php declare(strict_types=1); $base=config('app.base_path'); $o=$order; $status=$o['status']; $next=['PENDING'=>['ACCEPTED','REJECTED','CANCELLED'],'ACCEPTED'=>['PACKING','CANCELLED'],'PACKING'=>['READY','CANCELLED'],'READY'=>$o['order_type']==='DELIVERY'?['ASSIGNED']:['COMPLETED'],'ASSIGNED'=>['OUT_FOR_DELIVERY','CANCELLED'],'OUT_FOR_DELIVERY'=>['DELIVERED'],'DELIVERED'=>['COMPLETED']]; ?>
<div class="page-header"><div><h1>Order <?= htmlspecialchars($o['order_no'],ENT_QUOTES,'UTF-8') ?></h1><p><?= htmlspecialchars($o['business_name'],ENT_QUOTES,'UTF-8') ?> · <?= htmlspecialchars($o['status'],ENT_QUOTES,'UTF-8') ?></p></div><div class="page-actions"><a class="btn btn-secondary" href="<?= $base ?>/fresh-food/orders">All Orders</a></div></div>
<div class="grid"><div><div class="card"><h2>Order Details</h2><div class="details"><div><small>Customer</small><strong><?= htmlspecialchars($o['customer_name'],ENT_QUOTES,'UTF-8') ?></strong><?= !empty($o['customer_phone'])?'<span>'.htmlspecialchars($o['customer_phone'],ENT_QUOTES,'UTF-8').'</span>':'' ?></div><div><small>Type</small><strong><?= htmlspecialchars($o['order_type'],ENT_QUOTES,'UTF-8') ?></strong></div><div><small>Total</small><strong>₹<?= number_format((float)$o['total'],2) ?></strong></div><div><small>Payment</small><strong><?= htmlspecialchars($o['payment_status'],ENT_QUOTES,'UTF-8') ?></strong></div></div><?php if($o['order_type']==='DELIVERY'): ?><hr><strong>Delivery Address</strong><p><?= nl2br(htmlspecialchars((string)$o['delivery_address'],ENT_QUOTES,'UTF-8')) ?></p><p><?= htmlspecialchars(trim(($o['delivery_city']??'').' '.($o['delivery_district']??'').' '.($o['delivery_state']??'')),ENT_QUOTES,'UTF-8') ?></p><?php endif; ?></div><div class="card"><h2>Items</h2><table class="table"><thead><tr><th>Product</th><th>Qty</th><th>Unit Price</th><th>Discount</th><th>Total</th></tr></thead><tbody><?php foreach($o['items'] as $i): ?><tr><td><?= htmlspecialchars($i['product_name'],ENT_QUOTES,'UTF-8') ?></td><td><?= number_format((float)$i['quantity'],3) ?> <?= htmlspecialchars($i['unit'],ENT_QUOTES,'UTF-8') ?></td><td>₹<?= number_format((float)($i['original_unit_price']??$i['unit_price']),2) ?><?php if(($i['discount_type']??'NONE')!=='NONE'): ?><br><small><?= $i['discount_type']==='PERCENT'?number_format((float)$i['discount_value'],2).'%':'₹'.number_format((float)$i['discount_value'],2) ?></small><?php endif; ?></td><td>₹<?= number_format((float)($i['discount_amount']??$i['discount']??0),2) ?></td><td>₹<?= number_format((float)$i['line_total'],2) ?></td></tr><?php endforeach; ?></tbody></table><div class="summary">Gross Subtotal: ₹<?= number_format((float)$o['gross_subtotal'],2) ?><br>Item Discounts: ₹<?= number_format((float)($o['item_discount']??0),2) ?><br>Coupon<?= !empty($o['coupon_code'])?' ('.htmlspecialchars((string)$o['coupon_code'],ENT_QUOTES,'UTF-8').')':'' ?>: ₹<?= number_format((float)($o['coupon_discount']??0),2) ?><br>Manual Discount: ₹<?= number_format((float)$o['discount'],2) ?><br>Delivery: ₹<?= number_format((float)$o['delivery_fee'],2) ?><br><strong>Total: ₹<?= number_format((float)$o['total'],2) ?></strong></div></div></div>
<div><div class="card"><h2>Order Action</h2><?php if(!empty($next[$status])): foreach($next[$status] as $n): ?><form method="post" action="<?= $base ?>/fresh-food/orders/<?= (int)$o['id'] ?>/status" class="action-form"><input type="hidden" name="status" value="<?= $n ?>"><?php if(in_array($n,['REJECTED','CANCELLED'],true)): ?><textarea name="reason" required placeholder="Reason is required"></textarea><?php endif; ?><?php if($n==='ASSIGNED'): ?><select name="delivery_assigned_to" required><option value="">Select delivery person</option><?php foreach($deliveryUsers as $u): ?><option value="<?= (int)$u['id'] ?>"><?= htmlspecialchars($u['name'],ENT_QUOTES,'UTF-8') ?><?= !empty($u['phone'])?' — '.htmlspecialchars($u['phone'],ENT_QUOTES,'UTF-8'):'' ?></option><?php endforeach; ?></select><?php endif; ?><button class="btn <?= in_array($n,['REJECTED','CANCELLED'],true)?'btn-secondary':'btn-primary' ?>" type="submit"><?= ucwords(strtolower(str_replace('_',' ',$n))) ?></button></form><?php endforeach; else: ?><p>This order has no further workflow action.</p><?php endif; ?></div><div class="card"><h2>Status History</h2><ol class="timeline"><?php foreach($o['history'] as $h): ?><li><strong><?= htmlspecialchars($h['to_status'],ENT_QUOTES,'UTF-8') ?></strong><span><?= htmlspecialchars((string)$h['created_at'],ENT_QUOTES,'UTF-8') ?> · <?= htmlspecialchars((string)$h['changed_by_name'],ENT_QUOTES,'UTF-8') ?></span><?php if(!empty($h['note'])):?><p><?= htmlspecialchars($h['note'],ENT_QUOTES,'UTF-8') ?></p><?php endif; ?></li><?php endforeach; ?></ol></div></div></div>
<style>.grid{display:grid;grid-template-columns:2fr 1fr;gap:16px}.details{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.details div{display:flex;flex-direction:column;gap:4px}.summary{text-align:right;line-height:1.8;margin-top:16px}.action-form{display:flex;flex-direction:column;gap:8px;margin-bottom:12px}.action-form textarea,.action-form select{width:100%;box-sizing:border-box}.timeline{margin:0;padding-left:20px}.timeline li{margin-bottom:16px}.timeline span{display:block;font-size:12px;opacity:.7}.timeline p{margin:5px 0 0}.card h2{margin-top:0}@media(max-width:900px){.grid{grid-template-columns:1fr}}@media(max-width:600px){.details{grid-template-columns:1fr}}</style>
